def max_alternating_sum(arr):
    max_sum = float('-inf')
    curr_sum = 0
    for i in range(len(arr)):
        if i == 0 or (arr[i] % 2 != arr[i-1] % 2):
            curr_sum += arr[i]
        else:
            curr_sum = arr[i]
        max_sum = max(max_sum, curr_sum)
    return max_sum

