def maximumOr(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(k + 1):
            dp[i + 1][j] = max(dp[i][j], dp[i][j - 1] | nums[i])
            if j > 0:
                dp[i + 1][j] = max(dp[i + 1][j], dp[i][j - 1] | (nums[i] * 2))

    return dp[n][k]

