def min_length(s):
    stack = []
    for char in s:
        if stack and (char == 'B' and stack[-1] == 'A' or char == 'D' and stack[-1] == 'C'):
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

from math import gcd
from collections import defaultdict

def isPossible(nums):
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                graph[i].append(j)
                graph[j].append(i)
    visited = [False] * len(nums)
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
    for i in range(len(nums)):
        if not visited[i]:
            dfs(i)
    return all(visited)

def minOperations(num1, num2):
    if num1 < 0:
        return -1

    operations = 0
    while num1 > 0:
        if num2 >= num1:
            return -1
        num1 -= (1 << (num2 + 1))
        operations += 1

    return operations

def specialPermutation(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0]*n for _ in range(1<<n)]
    for i in range(n):
        dp[1<<i][i] = 1
    for mask in range(1<<n):
        for i in range(n):
            if mask & (1<<i):
                for j in range(n):
                    if mask & (1<<j) and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                        dp[mask][i] = (dp[mask][i] + dp[mask ^ (1<<i)][j]) % MOD
    return sum(dp[(1<<n)-1][i] for i in range(n)) % MOD

def maxJumps(nums, target):
    n = len(nums)
