def numberOfWays(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i - j**x >= 0:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def max_sum_equal_max_digit(nums):
    max_digit = -1
    max_sum = -1
    for num in nums:
        max_digit = max(max_digit, max(int(digit) for digit in str(num)))
        if max_digit != -1:
            for other_num in nums:
                if other_num != num and max(int(digit) for digit in str(other_num)) == max_digit:
                    max_sum = max(max_sum, num + other_num)
    return max_sum

MOD = 10**9 + 7

def count_stepping_numbers(low, high):
    def count_stepping_numbers_dp(n, low, high):
        if n == 0:
            return 1
        if n < 0 or n > len(high):
            return 0
        if n == len(low):
            return 1

        count = 0
        for i in range(10):
            if i > int(high[n-1]) - 1:
                break
            if i < int(low[n-1]) + 1:
                count += count_stepping_numbers_dp(n-1, low, high)
                count %= MOD
        return count

    return (count_stepping_numbers_dp(len(high)-1, low, high) - count_stepping_numbers_dp(len(low)-1, low, high) + MOD) % MOD

def minTime(nums1, nums2, x):
    n = len(nums1)
    dp = [[float('inf')] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(x + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums1[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums1[i - 1]] + 1)
            if j >= nums2[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums2[i - 1]] + 1)

    return dp[n][x] if dp[n][x] != float('inf') else -1

def maximizeTheProfit(n, offers):
    dp = [0] * (n + 1)
