from collections import defaultdict

def minCost(source, target, original, changed, cost):
    graph = defaultdict(list)
    for i in range(len(original)):
        graph[original[i]].append((changed[i], cost[i]))

    dp = [float('inf')] * 26
    dp[ord(source[0]) - ord('a')] = 0

    for i in range(1, len(source)):
        for c in range(26):
            if dp[c] != float('inf'):
                for j, z in graph[chr(c + ord('a'))]:
                    dp[j] = min(dp[j], dp[c] + z)

    return dp[ord(target[0]) - ord('a')] if dp[ord(target[0]) - ord('a')] != float('inf') else -1

