def count_non_ddos_strings(S):
    n = len(S)
    dp = [[0]*52 for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(52):
            dp[i+1][j] = dp[i][j]
            if S[i] == '?':
                for k in range(52):
                    dp[i+1][k] = (dp[i+1][k] + dp[i][k]) % MOD
            else:
                if S[i].isupper():
                    dp[i+1][ord(S[i]) - ord('A') + ord('A')] = (dp[i+1][ord(S[i]) - ord('A') + ord('A')] + dp[i][j]) % MOD
                else:
                    dp[i+1][ord(S[i]) - ord('a') + ord('A')] = (dp[i+1][ord(S[i]) - ord('a') + ord('A')] + dp[i][j]) % MOD

    return sum(dp[n]) % MOD

