def count_holeless_squares(H, W, N, holes):
    # Create a 2D array to mark the holed squares
    grid = [[0] * (W + 1) for _ in range(H + 1)]
    for a, b in holes:
        grid[a][b] = 1

    # Initialize the count of holeless squares
    count = 0

    # Iterate over all possible square sizes
    for n in range(1, min(H, W) + 1):
        # Iterate over all possible top-left corners
        for i in range(1, H - n + 2):
            for j in range(1, W - n + 2):
                # Check if the square region is holeless
                is_holeless = True
                for k in range(n):
                    for l in range(n):
                        if grid[i + k][j + l] == 1:
                            is_holeless = False
                            break
                    if not is_holeless:
                        break
                if is_holeless:
                    count += 1

    return count

