import heapq

def max_happiness(N, M, items):
    # Create a priority queue with the happiness values of the items
    pq = []
    for T, X in items:
        if T == 0:
            heapq.heappush(pq, (X, 0))
        elif T == 1:
            heapq.heappush(pq, (X, 1))
        else:
            heapq.heappush(pq, (X, 2))

    # Initialize the total happiness
    total_happiness = 0

    # Select the top M items with the highest happiness values
    for _ in range(M):
        happiness, opener_type = heapq.heappop(pq)
        if opener_type == 0:
            total_happiness += happiness
        elif opener_type == 1:
            total_happiness += happiness
        elif opener_type == 2:
            if len(pq) < M:
                heapq.heappush(pq, (happiness, 2))

    return total_happiness

