        if d == 1:
            return [i for i in range(1, 10)]
        else:
            return [i for i in range(9, 0, -1)] + generate_321_like_numbers(d-1)

    def find_kth_321_like_number_recursive(d, K):
        if d == 1:
            return K
        else:
            return find_kth_321_like_number_recursive(d-1, K)

    d = 1
    while True:
        nums = generate_321_like_numbers(d)
        if len(nums) >= K:
            return nums[K-1]
        d += 1

