def count_pairs(N, T, S):
    dp = [[0] * (len(T) + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        dp[i][0] = 1
    for i in range(1, N + 1):
        for j in range(1, len(T) + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0 and S[i - 1] == T[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]
    return sum(dp[i][len(T)] for i in range(N + 1))

