def solve(N, R, C):
    grid = [['.']*N for _ in range(N)]

    def is_valid(i, j):
        return grid[i][j] == '.' or grid[i][j] == R[i] or grid[i][j] == C[j]

    def backtrack(i, j):
        if i == N:
            return True
        if j == N:
            return backtrack(i+1, 0)
        if grid[i][j] != '.':
            return backtrack(i, j+1)
        for c in 'ABC':
            if is_valid(i, j):
                grid[i][j] = c
                if backtrack(i, j+1):
                    return True
                grid[i][j] = '.'
        return False

    if backtrack(0, 0):
        print("Yes")
        for row in grid:
            print(''.join(row))
    else:
        print("No")

