def min_operations(A, B):
    H, W = len(A), len(A[0])

    # Check if A is already equal to B
    if A == B:
        return 0

    # Create a list of all possible operations
    operations = []
    for i in range(H-1):
        operations.append((i, i+1))
    for j in range(W-1):
        operations.append((j, j+1))

    # Function to check if two grids are identical
    def is_identical(A, B):
        for i in range(H):
            for j in range(W):
                if A[i][j] != B[i][j]:
                    return False
        return True

    # Function to perform a swap operation
    def swap(A, i, j):
        A[i][j], A[i+1][j] = A[i+1][j], A[i][j]
        A[i][j], A[i][j+1] = A[i][j+1], A[i][j]
        A[i+1][j], A[i+1][j+1] = A[i+1][j+1], A[i+1][j]
        A[i][j], A[i][j+1] = A[i][j+1], A[i][j]
        A[i+1][j], A[i+1][j+1] = A[i+1][j+1], A[i+1][j]
        A[i][j], A[i][j+1] = A[i][j+1], A[i][j]
        A[i+1][j], A[i+1][j+1] = A[i+1][j+1], A[i+1][j]
        A[i][j], A[i][j+1] = A[i][j+1], A[i][j]
        A[i+1][j], A[i+1][j+1] = A[i+1][j+1], A[i+1][j]
        A[i][j], A[i][j+1] = A[i][j+1], A[i][j]
        A[i+1][j], A[i+1][j+1] = A[i+1][j+1], A[i+1][j]
        return A

    # Function to count the number of operations
    def count_operations(A, B):
        operations_count = 0
        for i in range(H-1):
            for j in range(W-1):
                if A[i][j] != B[i][j]:
                    operations_count += 1
                    A = swap(A, i, j)
        return operations_count

    # Check if A can be transformed into B
    for op in operations:
        A = swap(A, op[0], op[1])
        if is_identical(A, B):
            return count_operations(A, B)

    return -1

