def mod_inv(a, m):
    return pow(a, m-2, m)

def solve(H, W, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(i, j, visited):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '#' and (nx, ny) not in visited:
                    stack.append((nx, ny))

    def count_components():
        visited = set()
        components = 0
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '#' and (i, j) not in visited:
                    dfs(i, j, visited)
                    components += 1
        return components

    initial_components = count_components()
    total_components = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                grid[i][j] = '#'
                new_components = count_components()
                total_components += new_components
                grid[i][j] = '.'

    expected_value = (initial_components + total_components) * mod_inv(H * W, MOD) % MOD
    return expected_value

