def min_operations(H, W, K, grid):
    def count_operations(grid, H, W, K):
        operations = 0
        for i in range(H):
            for j in range(W - K + 1):
                if grid[i][j] == '.':
                    operations += 1
                    for k in range(K):
                        grid[i][j + k] = 'o'
        return operations

    def count_operations_vertical(grid, H, W, K):
        operations = 0
        for i in range(H - K + 1):
            for j in range(W):
                if grid[i][j] == '.':
                    operations += 1
                    for k in range(K):
                        grid[i + k][j] = 'o'
        return operations

    operations_horizontal = count_operations(grid, H, W, K)
    operations_vertical = count_operations_vertical(grid, H, W, K)

    if operations_horizontal < operations_vertical:
        return operations_horizontal
    elif operations_vertical < operations_horizontal:
        return operations_vertical
    else:
        return -1

