def min_moves(grid):
    N = len(grid)
    P1, P2 = None, None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                if P1 is None:
                    P1 = (i, j)
                else:
                    P2 = (i, j)
    if P1 is None or P2 is None:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = [(P1[0] - P2[0], P1[1] - P2[1], 0)]
    visited = set()
    visited.add((P1[0], P1[1]))

    while queue:
        dx, dy, moves = queue.pop(0)
        for dx_dir, dy_dir in directions:
            x, y = P1[0] + dx_dir, P1[1] + dy_dir
            if 0 <= x < N and 0 <= y < N and grid[x][y] == '.' and (x, y) not in visited:
                visited.add((x, y))
                queue.append((x, y, moves + 1))
                if (x, y) == P2:
                    return moves + 1
    return -1

