def count_possible_positions(H, W, N, T, grid):
    # Directions for L, R, U, D
    directions = {
        'L': (0, -1),
        'R': (0, 1),
        'U': (-1, 0),
        'D': (1, 0)
    }

    # Starting position
    start_positions = []
    for i in range(1, H-1):
        for j in range(1, W-1):
            if grid[i][j] == '.':
                start_positions.append((i, j))

    # Function to check if a position is valid
    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == '.'

    # Function to move in a given direction
    def move(x, y, direction):
        return (x + directions[direction][0], y + directions[direction][1])

    # BFS to find all possible positions
    queue = [(x, y) for x, y in start_positions if is_valid(x, y)]
    visited = set(queue)
    while queue:
        x, y = queue.pop(0)
        for direction in T:
            nx, ny = move(x, y, direction)
            if (nx, ny) not in visited and is_valid(nx, ny):
                visited.add((nx, ny))
                queue.append((nx, ny))

    return len(visited)

