def kth_smallest_divisible(N, M, K):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def count_divisible(N, M, K):
        count = 0
        for i in range(1, K + 1):
            if (i % N == 0 and i % M != 0) or (i % N != 0 and i % M == 0):
                count += 1
        return count

    def find_kth_divisible(N, M, K):
        low, high = 1, K * min(N, M)
        while low < high:
            mid = (low + high) // 2
            if count_divisible(N, M, mid) < K:
                low = mid + 1
            else:
                high = mid
        return low

    return find_kth_divisible(N, M, K)

