def max_degree_of_freedom(H, W, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False]*W for _ in range(H)]
    max_degree = 0

    def dfs(i, j):
        if visited[i][j]:
            return 0
        visited[i][j] = True
        degree = 1
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '.' and not visited[ni][nj]:
                degree += dfs(ni, nj)
        return degree

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and not visited[i][j]:
                max_degree = max(max_degree, dfs(i, j))

    return max_degree

