def longest_common_prefix(s1, s2):
    i = 0
    while i < len(s1) and i < len(s2) and s1[i] == s2[i]:
        i += 1
    return i

def solve(strings):
    n = len(strings)
    prefix_sum = [0] * n
    for i in range(n):
        for j in range(i+1, n):
            prefix_sum[j] += longest_common_prefix(strings[i], strings[j])
    return prefix_sum[-1]

