def find_bingo_turn(N, T, A):
    grid = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            grid[i][j] = N * (i-1) + j + 1

    for turn in range(T):
        for i in range(N):
            for j in range(N):
                if grid[i][j] == A[turn]:
                    return turn + 1
    return -1

