def has_palindrome_substring(s):
    for i in range(len(s)-1):
        if s[i:i+2] == s[::-1][i:i+2]:
            return True
    return False

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def max_prime_distance(nums):
    prime_indices = [i for i, num in enumerate(nums) if is_prime(num)]
    return max(prime_indices) - min(prime_indices)

def min_length(s):
    s = sorted(s)
    n = len(s)
    i = 0
    while i < n:
        if s[i] != s[i+1]:
            i += 1
        else:
            i += 2
    return i

def numStableArrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1

    for i in range(zero + 1):
        for j in range(one + 1):
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
            if i > 0 and j > 0:
                dp[i][j] = (dp[i][j] - dp[i - 1][j - 1] + MOD) % MOD

    return dp[zero][one]

def is_special(nums):
    for i in range(len(nums)-1):
        if (nums[i] % 2 == nums[i+1] % 2):
            return False
    return True

def sum_of_digit_differences(nums):
    num_str = [str(num) for num in nums]
    total_diff = 0
    for i in range(len(num_str)):
        for j in range(i+1, len(num_str)):
            total_diff += sum(1 for a, b in zip(num_str[i], num_str[j]) if a != b)
    return total_diff

def powerful_array(n):
    res = []
    while n:
        res.append(n & -n)
        n >>= 1
    return sorted(res)

def get_big_nums(n):
    big_nums = {}
    i = 1
    while True:
        powerful_array = powerful_array(i)
        if i not in big_nums:
            big_nums[i] = powerful_array
        else:
            big_nums[i] = big_nums[i] + powerful_array
        i += 1
        if i > n:
            break
    return big_nums

def product_mod(queries, big_nums, mod):
    answer = []
    for query in queries:
        from_i, to_i, mod_i = query
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        answer.append(product)
    return answer

def xor_twice(nums):
    xor_result = 0
    for num in nums:
        if nums.count(num) == 2:
            xor_result ^= num
    return xor_result

def findQueries(nums, queries, x):
    occurrences = []
    for num in nums:
        if num == x:
            occurrences.append(nums.index(num))
    return [occurrences[i] if i < len(occurrences) else -1 for i in queries]
